using System.Collections.Generic;

namespace SWLOR.Game.Server.Service.CraftService;

/// <summary>
/// The values one recipe gives the Engineering Circuit minigame. They are set by <c>.CircuitParameters(...)</c> in the recipe
/// definitions and generated by <see cref="CircuitParameterProfile"/>.
/// </summary>
public sealed class CircuitParameters : RecipeMinigameParameters
{
    private readonly IReadOnlyList<RecipeParameterValue> _values;

    /// <summary>
    /// Builds the values. The overload line is the Load above which actions can overload; the Load boost is the extra output
    /// each Load point gives; the Assembly share is how the recipe's work divides between the two meters.
    /// </summary>
    /// <param name="overloadLine">The highest Load that is safe. An action that leaves Load above it can overload.</param>
    /// <param name="loadBoostPercent">The percent each point of Load adds to the output of Wire, Tune and Discharge.</param>
    /// <param name="assemblySharePercent">
    /// The share of the recipe's work that is Assembly, out of 100. The rest is Calibration; 50 splits it evenly.
    /// </param>
    public CircuitParameters(int overloadLine, int loadBoostPercent, int assemblySharePercent)
    {
        OverloadLine = overloadLine;
        LoadBoostPercent = loadBoostPercent;
        AssemblySharePercent = assemblySharePercent;
        _values = new[]
        {
            new RecipeParameterValue("overloadLine", overloadLine),
            new RecipeParameterValue("loadBoostPercent", loadBoostPercent),
            new RecipeParameterValue("assemblySharePercent", assemblySharePercent)
        };
    }

    public int OverloadLine { get; }

    public int LoadBoostPercent { get; }

    public int AssemblySharePercent { get; }

    public override IReadOnlyList<RecipeParameterValue> Values => _values;

    /// <summary>The values a recipe without parameters plays with: the middle of every bound.</summary>
    public static CircuitParameters Fallback { get; } = new(6, 10, 50);
}
